def net_turns(steps):
    n = 0
    for s in steps:
        if s == 'l':
            n += 1
        elif s == 'L':
            n -= 1
    return n

def reduce(steps):
    out = []
    for s in steps:
        if out and out[-1] != s:
            out.pop()
        else:
            out.append(s)
    return out

def mix(colors):
    out = [0, 0, 0]
    for c in colors:
        for i in range(3):
            out[i] += c[i]
    return [min(255, v) for v in out]

