def discounted(rewards, gamma):
    t = 0.0
    g = 1.0
    for r in rewards:
        t += g * r
        g *= gamma
    return round(t, 6)

def upsilon(envs):
    t = 0.0
    for k, v in envs:
        t += v * (0.5 ** k)
    return round(t, 6)

def entropy(probs):
    import math
    h = 0.0
    for p in probs:
        if p > 0:
            h -= p * math.log(p) / math.log(2)
    return round(h, 6)

def text_entropy(s):
    import math
    if not s:
        return 0.0
    counts = {}
    for ch in s:
        counts[ch] = counts.get(ch, 0) + 1
    h = 0.0
    n = len(s)
    for ch in counts:
        p = counts[ch] / n
        h -= p * math.log(p) / math.log(2)
    return round(h, 4)

