practice.solution:
def generate(rules, start, max_len):
    seen = set([start])
    todo = [start]
    done = set()
    while todo:
        cur = todo.pop()
        idx = -1
        for i in range(len(cur)):
            if cur[i].isupper():
                idx = i
                break
        if idx < 0:
            done.add(cur)
            continue
        for lhs, rhs in rules:
            if cur[idx] == lhs:
                nxt = cur[:idx] + rhs + cur[idx + 1:]
                if len(nxt) <= max_len and nxt not in seen:
                    seen.add(nxt)
                    todo.append(nxt)
    return sorted(done)

