practice.solution:
def run_tm(rules, tape, steps):
    cells = {}
    for i in range(len(tape)):
        cells[i] = tape[i]
    state = 'q0'
    head = 0
    n = 0
    while state != 'halt' and n < steps:
        sym = cells.get(head, '_')
        rule = None
        for r in rules:
            if r[0] == state and r[1] == sym:
                rule = r
                break
        if rule is None:
            break
        cells[head] = rule[2]
        head += 1 if rule[3] == 'R' else -1
        state = rule[4]
        n += 1
    if not cells:
        return [state, '']
    lo = min(cells)
    hi = max(cells)
    out = ''
    for i in range(lo, hi + 1):
        out += cells.get(i, '_')
    return [state, out.strip('_')]

